import React from 'react';
import { Navbar } from './components/Navbar';
import Background from './components/Background';
// src/App.js or other component files
import { About, ContactMe, Home, Projects, Resume } from './components/pages';
import './App.css';

function App() {
  return (
    <div className="App">
      <Navbar />
      <Background />
      <div id="home" style={{ height: '100vh' }}> {/* Placeholder for Home section if you have separate content */}
        <h2>Home Section</h2>
      </div>
      <div id="about" style={{ height: '100vh' }}>
        <About />
      </div>
      <div id="projects" style={{ height: '100vh' }}>
        <Projects />
      </div>
      <div id="resume" style={{ height: '100vh' }}>
        <Resume />
      </div>
      <div id="contact" style={{ height: '100vh' }}>
        <ContactMe />
      </div>
    </div>
  );
}

export default App;
